import matplotlib.pyplot as plt

def plot_average_scores(student_data, bar_color='red'):
    # Check for negative scores
    for student in student_data:
        for score in student.values():
            if score is not None and score < 0:
                raise ValueError("Negative scores are not allowed.")

    # Combine the list of dictionaries into a single dictionary
    combined_data = {}
    for student in student_data:
        for key, value in student.items():
            if key not in combined_data:
                combined_data[key] = []
            if value is not None:
                combined_data[key].append(value)

    # Calculate the average score for each student
    average_scores = {}
    for student, scores in combined_data.items():
        if scores:
            average_scores[student] = sum(scores) / len(scores)

    # Create the bar chart
    plt.figure(figsize=(10, 6))
    plt.bar(average_scores.keys(), average_scores.values(), color=bar_color)
    plt.xlabel('Student')
    plt.ylabel('Average Score')
    plt.title('Average Student Scores')
    plt.xticks(rotation=45)
    plt.tight_layout()
    plt.show()

# Example usage:
student_data = [
    {'Alice': 85, 'Bob': 90, 'Charlie': 78},
    {'Alice': 88, 'Bob': 85, 'David': 92},
    {'Alice': 90, 'Bob': 80, 'Charlie': 82, 'David': 88}
]

plot_average_scores(student_data, bar_color='blue')
```

